// v2.55: a base pública pode conter vários MB de imagens embutidas. Elas devem aparecer
// imediatamente e de forma idêntica em PC/celular, sem depender de o aparelho conseguir
// primeiro copiar tudo para o IndexedDB. Para o espelho de localStorage, removemos somente
// data:image remotas; uploads locais continuam sendo idbimg: e permanecem preservados.
function localStorageSafeCloneV255(value,seen=new WeakMap()){
  if(value===null||value===undefined)return value;
  if(typeof value==='string')return /^data:image\//i.test(value)?'':value;
  if(typeof value!=='object')return value;
  if(seen.has(value))return seen.get(value);
  const out=Array.isArray(value)?[]:{}; seen.set(value,out);
  if(Array.isArray(value)){for(const x of value)out.push(localStorageSafeCloneV255(x,seen));}
  else{for(const [k,v] of Object.entries(value))out[k]=localStorageSafeCloneV255(v,seen);}
  return out;
}
function save(){
  try{
    // Normal path remains unchanged when the DB contains only compact idbimg refs.
    localStorage.setItem(KEY,JSON.stringify(db));
    return true;
  }catch(err){
    if(isQuotaErrorV234(err)){
      // v2.56: nunca transformar a base pública visível em referências idbimg:.
      // O PC e o celular devem manter exatamente as mesmas imagens recebidas da base pública
      // durante toda a sessão. O espelho local é compacto, mas a memória permanece intacta.
      try{
        localStorage.setItem(KEY,JSON.stringify(localStorageSafeCloneV255(db)));
      }catch(e){console.error('Persistência local compacta:',e)}
      return false;
    }
    throw err;
  }
}

