async function centralRead(action,params={}){
  if(action!=='bootstrapPublic'&&action!=='centralStatus'){
    throw new Error('Ação de leitura central não suportada.');
  }

  const response=await fetch('./data.json?v='+Date.now(),{
    method:'GET',
    cache:'no-store',
    credentials:'same-origin'
  });

  if(!response.ok)throw new Error('Base pública indisponível: HTTP '+response.status);

  const payload=await response.json();
  if(!payload?.ok)throw new Error(payload?.error||'Base pública inválida.');

  if(action==='centralStatus'){
    return {
      ok:true,
      version:payload.version||'',
      updatedAt:payload.updatedAt||''
    };
  }

  return payload;
}

function imageRefStatsV255(value){
  const stats={refs:0,dataImages:0,emptyImageFields:0};
  const walk=(v,key='')=>{
    if(typeof v==='string'){
      if(isImageRefV234(v))stats.refs++;
      else if(/^data:image\//i.test(v))stats.dataImages++;
      return;
    }
    if(!v||typeof v!=='object')return;
    if(Array.isArray(v)){v.forEach(x=>walk(x,key));return;}
    Object.entries(v).forEach(([k,x])=>walk(x,k));
  };
  walk(value); return stats;
}
function unresolvedImageRefsV255(value){
  let n=0; const walk=v=>{if(typeof v==='string'){if(isImageRefV234(v))n++;return;} if(!v||typeof v!=='object')return; if(Array.isArray(v))v.forEach(walk);else Object.values(v).forEach(walk)}; walk(value); return n;
}
function publicCentralSnapshot(){ensureNormasV174();return {rooms:db.rooms||[],categories:db.categories||[],products:db.products||[],availabilityClosures:db.availabilityClosures||[],leisureGuide:db.leisureGuide||[],versatilGuide:(db.versatilGuide||[]).filter(sec=>!isExcessNormasSectionV249(sec)),starlisGuide:db.starlisGuide||[],postalConfig:db.postalConfig||{}}}
async function publicCentralSnapshotWithImagesV234(){
  const light=publicCentralSnapshot();
  const before=imageRefStatsV255(light);
  const expanded=await expandImageRefsV234(light);
  const unresolved=unresolvedImageRefsV255(expanded);
  if(unresolved)throw new Error('Há '+unresolved+' imagem(ns) ainda não resolvida(s). A publicação foi interrompida para não gerar diferenças entre PC e celular.');
  const after=imageRefStatsV255(expanded);
  if(before.refs>0 && after.dataImages<before.refs){
    throw new Error('Nem todas as imagens locais puderam ser incorporadas à base pública ('+after.dataImages+'/'+before.refs+').');
  }
  return expanded;
}


function productPublicationSignatureV203(products){
  const rows=(Array.isArray(products)?products:[]).map(p=>[
    String(p.id||''),String(p.cat||''),String(p.name||''),String(p.icon||''),
    String(p.desc||''),Number(p.q||0),Number(p.a||0),p.halfDay===true
  ]);
  const str=JSON.stringify(rows);
  let h=2166136261;
  for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}
  return (h>>>0).toString(16);
}
function editorialPublicationSignatureV246(data){
  // Signature only over editorial fields stored losslessly in CONTENT. Other tables intentionally
  // normalize their schemas in Apps Script, so hashing the entire browser snapshot would differ.
  const editorial={
    categories:Array.isArray(data?.categories)?data.categories:[],
    products:Array.isArray(data?.products)?data.products:[],
    leisureGuide:Array.isArray(data?.leisureGuide)?data.leisureGuide:[],
    versatilGuide:Array.isArray(data?.versatilGuide)?data.versatilGuide:[],
    starlisGuide:Array.isArray(data?.starlisGuide)?data.starlisGuide:[],
    postalConfig:data?.postalConfig&&typeof data.postalConfig==='object'?data.postalConfig:{}
  };
  let str='';
  try{str=JSON.stringify(editorial)}catch(e){str=String(editorial||'')}
  let h=2166136261;
  for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}
  return (h>>>0).toString(16)+':'+str.length;
}
function publicationIdV245(){
  try{return crypto.randomUUID()}catch(e){return 'pub_'+Date.now()+'_'+Math.random().toString(36).slice(2)}
}
function setPendingPublicPublication(snapshot=null){
  const snap=snapshot||publicCentralSnapshot();
  const marker={
    at:Date.now(),
    iso:new Date().toISOString(),
    publicationId:publicationIdV245(),
    productsSignature:productPublicationSignatureV203(snap.products||[]),
    editorialSignature:editorialPublicationSignatureV246(snap)
  };
  localStorage.setItem(PENDING_PUBLICATION_KEY,JSON.stringify(marker));
  return marker;
}
function getPendingPublicPublication(){
  try{return JSON.parse(localStorage.getItem(PENDING_PUBLICATION_KEY)||'null')}catch(e){return null}
}
function clearPendingPublicPublication(){localStorage.removeItem(PENDING_PUBLICATION_KEY)}
function remotePublicationIsNewEnough(remoteUpdatedAt,pending){
  if(!pending)return true;
  const remoteMs=Date.parse(remoteUpdatedAt||'');
  if(!Number.isFinite(remoteMs))return false;
  return remoteMs >= (Number(pending.at||0)-2000);
}


