function applyRemotePublicDataV246(c,preserveLocal){
  c=c&&typeof c==='object'?c:{};
  if(preserveLocal){
    // Admin edits that have not yet been confirmed publicly must remain authoritative on this device.
    if(Array.isArray(c.rooms)&&c.rooms.length)db.rooms=conservativeRemoteMergeV238(db.rooms||[],c.rooms,'rooms');
    if(Array.isArray(c.categories)&&c.categories.length)db.categories=conservativeRemoteMergeV238(db.categories||[],c.categories,'categories');
    if(Array.isArray(c.products)&&c.products.length)db.products=conservativeRemoteMergeV238(db.products||[],c.products,'products');
    if(Array.isArray(c.availabilityClosures))db.availabilityClosures=conservativeRemoteMergeV238(db.availabilityClosures||[],c.availabilityClosures,'closures');
    if(Array.isArray(c.leisureGuide)&&c.leisureGuide.length)db.leisureGuide=conservativeRemoteMergeV238(db.leisureGuide||[],c.leisureGuide,'leisure');
    if(Array.isArray(c.versatilGuide)&&c.versatilGuide.length)db.versatilGuide=conservativeRemoteMergeV238(db.versatilGuide||[],c.versatilGuide,'versatil');
    if(Array.isArray(c.starlisGuide)&&c.starlisGuide.length)db.starlisGuide=conservativeRemoteMergeV238(normalizeStarlisStructureV235(db.starlisGuide||[]),normalizeStarlisStructureV235(c.starlisGuide),'starlis');
    if(c.postalConfig&&typeof c.postalConfig==='object')db.postalConfig={...(c.postalConfig||{}),...(db.postalConfig||{})};
    recoverVersatilV238();
    recoverStarlisV238();
    purgeDeletedEntitiesV243();
    restoreNormasDefinitiveV253();
    return;
  }

  // v2.47: after a confirmed publication (and on every client device), the public base is authoritative.
  // This prevents built-in/default descriptions such as "1 cama de solteiro" from masking Admin text.
  if(Array.isArray(c.rooms))db.rooms=cloneRemoteV246(c.rooms);
  if(Array.isArray(c.categories))db.categories=cloneRemoteV246(c.categories);
  if(Array.isArray(c.products))db.products=cloneRemoteV246(c.products);
  if(Array.isArray(c.availabilityClosures))db.availabilityClosures=cloneRemoteV246(c.availabilityClosures);
  if(Array.isArray(c.leisureGuide))db.leisureGuide=cloneRemoteV246(c.leisureGuide);
  if(Array.isArray(c.versatilGuide))db.versatilGuide=cloneRemoteV246(c.versatilGuide);
  if(Array.isArray(c.starlisGuide))db.starlisGuide=normalizeStarlisStructureV235(cloneRemoteV246(c.starlisGuide));
  if(c.postalConfig&&typeof c.postalConfig==='object')db.postalConfig=cloneRemoteV246(c.postalConfig);
  restoreNormasDefinitiveV253();
}

async function loadCentralData(options={}){
  const force=!!options.force;
  const quiet=!!options.quiet;
  const leisureOpenBefore=page==='leisure'?leisureOpenIds():[];
  if(!quiet)showVersatilLoading('Sincronizando dados…');

  if(centralSyncInFlight)return;
  if(!force && centralLastSyncAt && Date.now()-centralLastSyncAt<5000)return;

  centralSyncInFlight=true;
  if(!quiet){
    centralDataStatus='carregando';
    updateCentralStatusUI();
  }

  try{
    const p=await centralRead('bootstrapPublic');
    if(!p?.ok)throw new Error(p?.error||'Resposta inválida.');

    const pending=getPendingPublicPublication();
    const c=p.data||{};
    if(pending){
      const remoteProductsSignature=productPublicationSignatureV203(c.products||[]);
      const pendingProductsSignature=String(pending.productsSignature||'');
      const isNewEnough=remotePublicationIsNewEnough(p.updatedAt,pending);
      const sameProducts=!pendingProductsSignature || remoteProductsSignature===pendingProductsSignature;

      if(!isNewEnough || !sameProducts){
        // Critical: never overwrite a just-edited local product with stale/different public data.
        centralDataStatus='publicando';
        updateCentralStatusUI();
        setTimeout(async()=>{if(!(await verifyPendingPublicationV203(0)))setTimeout(()=>verifyPendingPublicationV203(1),5000)},3000);
        return;
      }
    }

    const preserveLocalPublicEdits=shouldPreserveLocalPublicEditsV246();
    applyRemotePublicDataV246(c,preserveLocalPublicEdits);
    db.centralVersion=p.version||'';
    db.centralUpdatedAt=p.publishedAt||p.updatedAt||'';

    // v2.55: use the exact public payload in memory first. Thus PC and celular see the same
    // texts/images even if one device has little IndexedDB quota. Persistence runs afterward.
    // A compact local mirror is enough for fallback; the authoritative public base is fetched
    // again on every synchronization.
    try{localStorage.setItem(KEY,JSON.stringify(localStorageSafeCloneV255(db)))}catch(e){console.warn('Espelho local compacto:',e)}
    if(pending)clearPendingPublicPublication();

    centralLastSyncAt=Date.now();
    localStorage.setItem('versatil_public_last_sync',String(centralLastSyncAt));
    centralDataStatus='ok';

    // v2.56: não converter imagens públicas em idbimg: depois do carregamento.
    // Essa conversão fazia a mesma base renderizar de forma diferente entre dispositivos.
    // As imagens públicas permanecem no formato recebido (data:image/URL) durante a sessão.
    hydrateStoredImagesInDomV234(document);

    if(p.version&&remoteVersionIsNewerV219(p.version,APP_VERSION)){
      centralDataStatus='atualizacao';
      showMandatoryUpdateNotice(p.version);
      return;
    }

    if(!session && document.querySelector('.login')){
      // v2.50: sincronização em segundo plano nunca reconstrói a tela de acesso.
      // Isso elimina a piscada e preserva o modo Admin aberto e os campos digitados.
      updateCentralStatusUI();
    }else if(session?.role==='admin' && quiet){
      updateCentralStatusUI();
    }else if(['leisure','versatil','starlis','postal'].includes(page)){
      updateCentralStatusUI();
      if(page==='leisure')setTimeout(()=>setupLeisureExclusiveAccordion(),0);
    }else{
      render();
    }
  }catch(err){
    console.warn('Base pública:',err);
    centralDataStatus='offline';
    localStorage.setItem('versatil_central_last_error',String(err?.message||err));
    if(!quiet)render();
    else updateCentralStatusUI();
  }finally{
    centralSyncInFlight=false;
    if(!quiet)hideVersatilLoading();
  }
}


function centralPost(action,payload={}){
  const body=JSON.stringify({action,clientVersion:APP_VERSION,...payload});
  const options={
    method:'POST',
    mode:'no-cors',
    cache:'no-store',
    headers:{'Content-Type':'text/plain;charset=utf-8'},
    body
  };
  // Fetch with keepalive is limited to about 64 KiB in browsers.
  // The public database is larger than that, so savePublicData must use a normal request.
  if(action!=='savePublicData'&&action!=='sendPostcard')options.keepalive=true;
  return fetch(GOOGLE_APPS_SCRIPT_URL+'?v='+APP_VERSION+'&t='+Date.now(),options);
}

function sleepV245(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function verifyPendingPublicationV203(attempt=0,options={}){
  const pending=getPendingPublicPublication();
  if(!pending)return true;
  try{
    const p=await centralRead('bootstrapPublic');
    if(!p?.ok)throw new Error(p?.error||'Resposta inválida');

    // v2.45: confirmation is tied to this exact publication, not only to products or timestamp.
    const remotePublicationId=String(p.publicationId||'');
    const exactPublication=!!pending.publicationId && remotePublicationId===String(pending.publicationId);
    const expectedEditorialSignature=String(pending.editorialSignature||'');
    const remoteEditorialSignature=expectedEditorialSignature?editorialPublicationSignatureV246(p?.data||{}):'';
    const sameEditorial=!expectedEditorialSignature || remoteEditorialSignature===expectedEditorialSignature;

    // Backward compatibility for a publication started by an older version.
    const remoteProducts=p?.data?.products||[];
    const sameProducts=productPublicationSignatureV203(remoteProducts)===String(pending.productsSignature||'');
    const newEnough=remotePublicationIsNewEnough(p.updatedAt,pending);
    const legacyConfirmed=!pending.publicationId && sameProducts && newEnough;

    if((exactPublication&&sameEditorial&&sameProducts)||legacyConfirmed){
      clearPendingPublicPublication();
      clearAdminLocalDirtyV226();
      localStorage.removeItem('versatil_admin_unsaved_public_changes');
      db.centralUpdatedAt=p.publishedAt||p.updatedAt||pending.iso;
      centralDataStatus='ok';
      save();
      updateCentralStatusUI();
      return true;
    }

    centralDataStatus='publicando';
    updateCentralStatusUI();
    return false;
  }catch(e){
    console.warn('Verificação de publicação:',e);
    return false;
  }
}
async function waitForPublicationConfirmationV245(maxAttempts=24,delayMs=3000){
  for(let i=0;i<maxAttempts;i++){
    if(await verifyPendingPublicationV203(i,{foreground:true}))return true;
    await sleepV245(delayMs);
  }
  return false;
}
async function publishPublicDataToCentral(showMessage=true){
  createEditorialBackupV238();
  await migrateEmbeddedImagesV234(db);
  save();
  const snapshot=await publicCentralSnapshotWithImagesV234();
  const marker=setPendingPublicPublication(snapshot);
  markAdminLocalDirtyV226();
  centralDataStatus='publicando';
  updateCentralStatusUI();

  try{
    // no-cors can confirm only that the browser sent the request. Real success is confirmed below by data.json.
    await centralPost('savePublicData',{data:snapshot,clientPublishedAt:marker.iso,publicationId:marker.publicationId});
    const confirmed=await waitForPublicationConfirmationV245();

    if(!confirmed){
      centralDataStatus='erro_publicacao';
      updateCentralStatusUI();
      if(showMessage)alert('A publicação não foi confirmada pela base pública. Suas alterações continuam salvas neste aparelho e permanecem marcadas como não publicadas.');
      return false;
    }

    if(showMessage)alert('Publicação concluída e confirmada na base pública.');
    return true;
  }catch(e){
    console.error('Falha ao publicar base:',e);
    centralDataStatus='erro_publicacao';
    updateCentralStatusUI();
    if(showMessage)alert('Falha ao publicar. Suas alterações permanecem salvas neste aparelho e não foram marcadas como publicadas.');
    return false;
  }
}

function saveAndPublishPublicData(showMessage=false){save();publishPublicDataToCentral(showMessage)}

function centralStatusLabel(){
  if(centralDataStatus==='ok'){
    const stamp=db.centralUpdatedAt
      ?new Date(db.centralUpdatedAt).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})
      :'';
    return stamp?`Base pública atualizada • ${stamp}`:'Base pública atualizada';
  }
  if(centralDataStatus==='offline')return 'Modo local';
  if(centralDataStatus==='atualizacao')return 'Atualização necessária';
  if(centralDataStatus==='publicando')return 'Publicando alterações…';
  if(centralDataStatus==='erro_publicacao')return 'Publicação não confirmada';
  return 'Sincronizando…';
}

function centralStatusHtml(){
  const publishing=centralDataStatus==='publicando'?' publishing-status-sweep-v242':'';
  return `<button id="centralStatusBadge" class="central-status ${centralDataStatus}${publishing}" onclick="loadCentralData({force:true})" title="Clique para atualizar agora">${centralStatusLabel()}</button>`;
}

function updateCentralStatusUI(){
  const label=centralStatusLabel();
  const isPublishing=centralDataStatus==='publicando';

  const el=document.getElementById('centralStatusBadge');
  if(el){
    el.textContent=label;
    el.className='central-status '+centralDataStatus+(isPublishing?' publishing-status-sweep-v242':'');
  }

  const text=document.getElementById('centralStatusTextV174');
  if(text){
    text.textContent=label;
    text.classList.toggle('publishing-text-sweep-v242',isPublishing);
  }

  const textV175=document.getElementById('centralStatusTextV175');
  if(textV175){
    textV175.textContent=label.replace('Base pública atualizada • ','Atualizado ').replace('Base pública atualizada','Atualizado');
    textV175.classList.toggle('publishing-text-sweep-v242',isPublishing);
  }
}


function versionPartsV219(v){
  return String(v||'').trim().replace(/^v/i,'').split('.').map(x=>Number(String(x).replace(/\D.*$/,''))||0);
}
function remoteVersionIsNewerV219(remote,local){
  const a=versionPartsV219(remote),b=versionPartsV219(local);
  const n=Math.max(a.length,b.length);
  for(let i=0;i<n;i++){
    const av=a[i]||0,bv=b[i]||0;
    if(av>bv)return true;
    if(av<bv)return false;
  }
  return false;
}

function showMandatoryUpdateNotice(serverVersion){
  document.getElementById('mandatoryUpdateModal')?.remove();
  const m=document.createElement('div');m.id='mandatoryUpdateModal';m.className='modal-overlay';
  m.innerHTML=`<div class="modal-card" style="max-width:520px"><h2>Atualização disponível</h2><p>Há uma versão mais recente do aplicativo.</p><div class="notice"><b>Instalada:</b> v${esc(APP_VERSION)}<br><b>Atual:</b> v${esc(serverVersion)}</div><button class="btn primary" style="width:100%" onclick="forceAppUpdate()">Atualizar agora</button></div>`;
  document.body.appendChild(m);
}
async function forceAppUpdate(){
  const btn=document.querySelector('#mandatoryUpdateModal .btn.primary');
  if(btn){btn.disabled=true;btn.textContent='Atualizando...'}
  try{
    if('serviceWorker' in navigator){
      const regs=await navigator.serviceWorker.getRegistrations();
      for(const r of regs){
        try{await r.unregister()}catch(e){}
      }
    }
    if('caches' in window){
      const keys=await caches.keys();
      await Promise.all(keys.map(k=>caches.delete(k)));
    }
    try{localStorage.removeItem('versatil_public_last_sync')}catch(e){}
    const u=new URL(location.href);
    u.searchParams.set('v','2300');
    u.searchParams.set('fresh',Date.now());
    location.replace(u.toString());
  }catch(e){
    console.error('Falha ao atualizar app:',e);
    if(btn){btn.disabled=false;btn.textContent='Tentar atualizar novamente'}
    alert('Não foi possível concluir a atualização automática. Feche esta aba e abra o aplicativo novamente.');
  }
}
function ensureVersatilLoader(){
  if(document.getElementById('versatilLoadingOverlay'))return;

  const overlay=document.createElement('div');
  overlay.id='versatilLoadingOverlay';
  overlay.className='versatil-loading-overlay';
  overlay.innerHTML=`<div class="versatil-loading-card">
    <div class="versatil-tetris-loader">
      <div class="versatil-tetris-base">
        <img class="versatil-tetris-ghost" src="logo-versatil.jpg" alt="">
        <div class="versatil-tetris-grid" id="versatilTetrisGrid"></div>
      </div>
    </div>
    <div id="versatilLoadingText" class="versatil-loading-text">Aguarde…</div>
  </div>`;
  document.body.appendChild(overlay);

  const grid=document.getElementById('versatilTetrisGrid');
  if(grid){
    const order=[
      30,31,32,33,34,35,
      24,25,27,28,26,29,
      18,20,19,23,21,22,
      12,13,17,14,16,15,
      6,11,7,9,10,8,
      0,5,1,4,2,3
    ];
    for(let i=0;i<36;i++){
      const cell=document.createElement('div');
      cell.className='versatil-tetris-piece';
      const row=Math.floor(i/6),col=i%6;
      cell.style.setProperty('--bg-x',`${-col*20}px`);
      cell.style.setProperty('--bg-y',`${-row*20}px`);
      const seq=order.indexOf(i);
      cell.style.animationDelay=`${seq*0.035}s`;
      grid.appendChild(cell);
    }
  }
}

function showVersatilLoading(message='Aguarde…'){
  ensureVersatilLoader();
  const overlay=document.getElementById('versatilLoadingOverlay');
  const txt=document.getElementById('versatilLoadingText');
  if(txt){
    txt.textContent=message;
    const publishing=/^Publicando alterações/i.test(String(message||''));
    txt.classList.toggle('publishing-shimmer-v233',publishing);
    txt.classList.toggle('publishing-text-sweep-v242',publishing);
  }
  if(overlay)overlay.classList.add('show');
}

function hideVersatilLoading(){
  document.getElementById('versatilLoadingOverlay')?.classList.remove('show');
}

async function withVersatilLoading(message,action){
  showVersatilLoading(message);
  try{
    return await action();
  }finally{
    hideVersatilLoading();
  }
}

async function publishWithLoading(){
  return withVersatilLoading('Publicando alterações…',async()=>{
    await publishPublicDataToCentral(true);
  });
}




const ITINERARY_KEY='versatil_my_itinerary';
let myItinerary=[];
try{myItinerary=JSON.parse(localStorage.getItem(ITINERARY_KEY)||'[]')||[]}catch(e){myItinerary=[]}
function saveMyItinerary(){localStorage.setItem(ITINERARY_KEY,JSON.stringify(myItinerary))}
function itineraryNodeById(id){return (db.leisureGuide||[]).find(n=>n.id===id&&n.type==='place')}
function itineraryHas(id){return myItinerary.some(x=>x.id===id)}
function addToItinerary(id){
  const p=itineraryNodeById(id);if(!p)return;
  if(itineraryHas(id)){showLeisureToast('Este local já está no seu roteiro.');return}
  myItinerary.push({id:p.id,name:p.name,distance:p.distance||'',mapQuery:p.mapQuery||p.name,addedAt:new Date().toISOString()});
  saveMyItinerary();updateItineraryCountUI();showLeisureToast('Adicionado ao MEU ROTEIRO.');
}
function removeFromItinerary(id){myItinerary=myItinerary.filter(x=>x.id!==id);saveMyItinerary();render()}
function clearMyItinerary(){if(myItinerary.length&&confirm('Limpar todos os locais do seu roteiro?')){myItinerary=[];saveMyItinerary();render()}}
function updateItineraryCountUI(){document.querySelectorAll('[data-itinerary-count]').forEach(el=>el.textContent=myItinerary.length?` (${myItinerary.length})`:'')}
function showLeisureToast(text){
  let t=document.getElementById('leisureToast');
  if(!t){t=document.createElement('div');t.id='leisureToast';t.className='leisure-toast';document.body.appendChild(t)}
  t.textContent=text;t.classList.add('show');clearTimeout(window._leisureToastTimer);window._leisureToastTimer=setTimeout(()=>t.classList.remove('show'),1800);
}
function itineraryMapUrl(item){
  const q=item?.mapQuery||item?.name||'';if(/^https?:\/\//i.test(q))return q;
  return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
}
function itineraryPage(){
  const items=myItinerary.map(x=>itineraryNodeById(x.id)||x);
  return `<div class="card itinerary-page">
    <div class="row between itinerary-head"><div><h2 class="itinerary-title-v184"><span class="itinerary-title-icon-v184">${UI_ICONS.map}</span><span>Meu roteiro</span></h2><p class="muted">${items.length?`${items.length} local(is) selecionado(s).`:'Nenhum local selecionado ainda.'}</p></div>${items.length?`<button class="btn red small" onclick="clearMyItinerary()">Limpar roteiro</button>`:''}</div>
    ${items.length?`<div class="itinerary-list">${items.map((p,i)=>`<div class="itinerary-item">
      <div class="itinerary-number">${i+1}</div><div class="itinerary-copy"><b>${esc(p.name)}</b><div class="small muted">${esc(p.distance||'')}</div></div>
      <a class="btn small" href="${esc(itineraryMapUrl(p))}" target="_blank" rel="noopener">Maps</a><button class="btn red small" onclick="removeFromItinerary('${esc(p.id)}')">Excluir</button>
    </div>`).join('')}</div>
    <div class="itinerary-confirm-box"><p><b>Ao confirmar, você receberá o roteiro em seu e-mail. Aproveite sua estada em Cuiabá!</b></p><button class="btn primary" onclick="confirmMyItinerary()">Confirmar roteiro</button></div>`:
    `<div class="notice">Abra <b>Lazer e Conveniências</b> e use o botão <b>Enviar para Roteiro</b> nos locais desejados.</div>`}
  </div>`;
}
async function confirmMyItinerary(){
  if(!myItinerary.length){alert('Seu roteiro está vazio.');return}
  const email=session?.email||'';if(!email){alert('Não foi possível identificar o e-mail deste acesso.');return}
  const items=myItinerary.map(x=>itineraryNodeById(x.id)||x).map(p=>({id:p.id,name:p.name,distance:p.distance||'',mapQuery:p.mapQuery||p.name}));
  showVersatilLoading('Enviando seu roteiro…');
  try{
    await fetch(GOOGLE_APPS_SCRIPT_URL,{method:'POST',mode:'no-cors',cache:'no-store',keepalive:true,headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'sendItinerary',clientVersion:APP_VERSION,client:{name:session?.name||'',email,roomName:session?.roomName||session?.room||''},items})});
    setSessionActivity('route');alert('Roteiro enviado para o seu e-mail. Aproveite sua estada em Cuiabá!');
    setTimeout(()=>loadCentralData({force:true,quiet:true}),2500);
  }catch(e){alert('Não foi possível enviar o roteiro agora. Tente novamente.')}finally{hideVersatilLoading()}
}


