const UPA_CATEGORY_ICON_V191='data:image/png;base64,';
const RODIZIOS_ICON_V194='data:image/png;base64,';
function leisureDisplayNameV170(node,depth){
  // v2.49: o texto exibido é sempre exatamente o texto salvo pelo Admin.
  // Regras antigas encurtavam/normalizavam títulos (ex.: ALIMENTAÇÃO),
  // fazendo edições maiores parecerem não salvas na área Cliente.
  return String(node?.name||'');
}
function leisureSemanticNameV248(node,depth){
  // Identidade visual separada do título editável.
  // Assim o usuário pode renomear uma categoria sem perder o ícone padrão.
  const id=String(node?.id||'');
  const raw=String(node?.name||'').trim().toLowerCase();
  if(depth===1){
    if(id==='lz_002')return 'turismo';
    if(id==='lz_060')return 'conveniências';
    if(id==='lz_104')return 'alimentação';
    if(id==='lz_244')return 'espaços de eventos';
    if(id==='grp_teatros_v171')return 'teatros';
    if(id==='grp_hospitais_v171')return 'hospitais e upa';
  }
  const aliases={
    'shoppings':'shopping',
    'happy hour / jantar':'happy hour',
    'cachorro quente (baguncinha & prensados)':'cachorro quente',
    'centros de convenções':'centro de eventos'
  };
  return aliases[raw]||raw;
}
function leisureGroupIconV170(node,depth){
  const custom=customIconHtmlV232(node,'leisure-uploaded-icon-v232');
  if(custom)return custom;
  const n=leisureSemanticNameV248(node,depth);
  if(String(node?.parentId||'')==='fish_root_v196')return `<img class="leisure-group-icon-img fishing-subcategory-icon-v208" src="icon-pesca-subcategorias.jpg" alt="" aria-hidden="true">`;
  if(n==='conveniências'||n==='conveniencias')return `<img class="leisure-group-icon-img conveniencias-user-icon-v206" src="icon-conveniencias-24h.jpg" alt="" aria-hidden="true">`;
  if(n==='cinemas')return `<span class="cinema-clapper-v201" aria-hidden="true">🎬</span>`;
  if(n==='pesca esportiva')return `<span class="fishing-icon-v196" aria-hidden="true">🎣</span>`;
  if(n==='rodízios'||n==='rodizios')return categoryImageIconV183(RODIZIOS_ICON_V194,'rodizios-user-icon-v194');
  if(n==='hamburguerias')return `<span class="single-burger-v193" aria-hidden="true">🍔</span>`;
  if(n==='hospitais')return UI_ICONS.hospitalRed;
  if(n==='upa')return categoryImageIconV183(UPA_CATEGORY_ICON_V191,'upa-category-v191');
  if(depth===1){
    if(n==='turismo')return UI_ICONS.map;
    if(n==='conveniências')return convenienceCategoryIconV189();
    if(n==='alimentação')return categoryImageIconV183(UI_CATEGORY_ASSETS_V183.alimentacao,'leisure-category-image');
    if(n==='espaços de eventos')return UI_ICONS.event;
    if(n==='teatros')return `<span class="emoji-group-icon">🎭</span>`;
    if(n==='hospitais e upa')return UI_ICONS.hospitalRed;
  }
  if(n==='parques')return UI_ICONS.tree;
  if(n==='museus')return UI_ICONS.museum;
  if(n==='aquários')return UI_ICONS.fishgold;
  if(n==='marcos geográficos')return UI_ICONS.pin;
  if(n==='locais turísticos')return UI_ICONS.map;
  if(n==='restaurantes')return UI_ICONS.restaurant;
  if(n==='bares')return UI_ICONS.drink;
  if(n==='lanchonetes')return UI_ICONS.burger;
  if(n==='pizzarias')return UI_ICONS.pizza;
  if(n==='rodízios')return UI_ICONS.skewer;
  if(n==='buffets')return UI_ICONS.cloche;
  if(n==='sport')return UI_ICONS.americanFootball;
  const symbol={
    'massas':'🍝','peixes':'🐟','carnes':'🥩','orientais':'🍣','regionais':'🍗','feijoadas':UI_ICONS.feijoadaClay,
    'happy hour':'🍻','noite':UI_ICONS.discoBall,'hamburguerias':'🍔🍟','espetinhos':'🍢','cachorro quente':'🌭',
    'mercados':'🛒','farmácias':UI_ICONS.pharmacyGreen,'posto de combustível':'⛽','shopping':'🛍️','mecânico':'🔧','cartório':'📄',
    'centro de eventos':'🏟️','festas e buffets':'🎈'
  }[n];
  return symbol?(String(symbol).startsWith('<svg')?symbol:`<span class="emoji-group-icon">${symbol}</span>`):'';
}
function leisureGroupSubtitleV170(node,depth){
  return leisureDisplayNameV170(node,depth)==='Rodízios'?'Carnes / Peixes / Orientais / Pizzarias':'';
}



function normalizeLocaisTuristicosV192(){
  if(!Array.isArray(db.leisureGuide))return;
  const root=db.leisureGuide.find(n=>n.id==='lz_036'||(n.type==='group'&&String(n.name||'').toLowerCase()==='locais turísticos'));
  if(!root)return;

  const subgroupIds=new Set(['lz_041','lz_046','lz_051','lz_054','lz_057']);
  db.leisureGuide.forEach(n=>{
    if(n.type==='place'&&subgroupIds.has(String(n.parentId||'')))n.parentId=root.id;
  });
  db.leisureGuide=db.leisureGuide.filter(n=>!subgroupIds.has(String(n.id||'')));

  // Keep the 18 original locations and their existing data, ordered by distance by leisureChildren().
  const wanted=new Set([
    'Centro Histórico e Catedral Basílica do Bom Jesus',
    'Mercado do Porto',
    'Parque das Águas e Parque Mãe Bonifácia',
    'Orla do Porto',
    'Aquário Encantado e Rio Salobra',
    'Cachoeira da Serra Azul',
    'Lagoa das Araras',
    'Reino Encantado e Estância Duto do Quebó',
    'Cachoeira Véu de Noiva',
    'Cidade de Pedra e Mirante Morro dos Ventos',
    'Circuito das Cachoeiras',
    'Complexo Turístico da Salgadeira',
    'Rodovia Transpantaneira',
    'Pousadas Pantaneiras',
    'Esportes de Aventura no Rio Tenente Amaral',
    'Cachoeira da Fumaça e Balneário Thermas',
    'Morro de Santo Antônio',
    'Turismo Fluvial'
  ]);
  const direct=db.leisureGuide.filter(n=>n.parentId===root.id&&n.type==='place');
  // Do not remove Admin-added places; this validation only guarantees the original 18 remain direct children.
  const originalCount=direct.filter(n=>wanted.has(String(n.name||''))).length;
  root.description=originalCount>=18?'18 locais turísticos e passeios cadastrados.':root.description;
}



