function enterClientV219(ev){
  try{
    if(ev){ev.preventDefault();ev.stopPropagation()}
    setClientAccessStatusV219('Validando acesso…','info');

    const email=document.getElementById('c_email')?.value.trim()||'';
    const name=document.getElementById('c_name')?.value.trim()||'';
    const unitValue=document.getElementById('c_room')?.value.trim()||'';

    if(!email||!name||!unitValue){
      setClientAccessStatusV219('Preencha e-mail, nome e quarto/apartamento.','error');
      return false;
    }

    const registered=findRegisteredRoom(unitValue);
    if(!registered){
      setClientAccessStatusV219('Unidade não existente. Confira o número do quarto/apartamento.','error');
      return false;
    }

    session={
      role:'client',
      email,
      name,
      roomId:registered.id,
      roomName:roomLabel(registered)
    };
    try{sessionStorage.setItem('versatil_menu_anim_access_v219',String(Date.now()))}catch(e){}

    cart=[];
    selectedCat='';
    expandedClientProductId='';
    page='catalog';

    setClientAccessStatusV219('Acesso confirmado. Abrindo aplicativo…','ok');
    render();
    return false;
  }catch(err){
    console.error('Falha no acesso do cliente:',err);
    setClientAccessStatusV219('Erro ao entrar: '+String(err?.message||err),'error');
    return false;
  }
}
function enterAdminV219(ev){
  try{
    if(ev){ev.preventDefault();ev.stopPropagation()}
    adminLogin();
  }catch(err){
    console.error('Falha no acesso Admin:',err);
    alert('Erro ao entrar no Admin: '+String(err?.message||err));
  }
  return false;
}

function clientLogin(){
  const email=document.getElementById("c_email").value.trim();
  const name=document.getElementById("c_name").value.trim();
  const unitValue=document.getElementById("c_room").value.trim();

  if(!email||!name||!unitValue){
    alert("Preencha e-mail, nome e quarto/apartamento.");
    return;
  }

  const registered=findRegisteredRoom(unitValue);
  if(!registered){
    alert("Unidade não existente");
    return;
  }

  session={
    role:"client",
    email,
    name,
    roomId:registered.id,
    roomName:roomLabel(registered)
  };
  try{sessionStorage.removeItem(POSTAL_SENT_ACCESS_KEY)}catch(e){}
  cart=[];
  selectedCat="";
  expandedClientProductId="";
  page="catalog";
  render();
}
function adminLogin(){
  const n=document.getElementById("a_name").value.trim();
  const p=document.getElementById("a_pass").value;
  if(n===db.account.adminName && p===db.account.adminPassword){
    session={role:"admin",name:n};
    adminPage="dashboard";
    render();
  }else{
    alert("Acesso administrativo inválido.");
  }
}


function recoverAdmin(){
  const primary=(db.account.recoveryEmail||'anibal@starlis.com.br').trim();
  if(!primary)return alert('Cadastre o e-mail principal de recuperação da conta.');

  const btn=document.activeElement;
  if(btn)btn.disabled=true;

  fetch(GOOGLE_APPS_SCRIPT_URL,{
    method:'POST',
    mode:'no-cors',
    cache:'no-store',
    headers:{'Content-Type':'text/plain;charset=UTF-8'},
    body:JSON.stringify({
      action:'recoverAdminPassword',
      email:primary,
      password:db.account.adminPassword,
      adminName:db.account.adminName||'Admin',
      clientVersion:'1.37'
    })
  }).then(()=>{
    alert(`Solicitação enviada. A recuperação de senha foi encaminhada somente para o e-mail principal: ${primary}`);
  }).catch(err=>{
    console.error(err);
    alert('Não foi possível solicitar a recuperação de senha. Tente novamente.');
  }).finally(()=>{if(btn)btn.disabled=false});
}



function requestPostalLandscapeV250(){
  const shell=document.getElementById('postalFullscreenV250');
  if(!shell||!window.matchMedia?.('(max-width:900px)')?.matches)return;
  try{
    const req=shell.requestFullscreen||shell.webkitRequestFullscreen;
    if(req){
      const result=req.call(shell);
      Promise.resolve(result).then(()=>{
        try{screen.orientation?.lock?.('landscape').catch?.(()=>{})}catch(e){}
      }).catch(()=>{});
    }else{
      try{screen.orientation?.lock?.('landscape').catch?.(()=>{})}catch(e){}
    }
  }catch(e){console.info('Tela cheia/orientação indisponível neste navegador.',e)}
}
