let postalCompositionDraftV249=null;
function newPromoCodeV249(){
  const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const bytes=new Uint8Array(12);
  try{crypto.getRandomValues(bytes)}catch(e){for(let i=0;i<bytes.length;i++)bytes[i]=Math.floor(Math.random()*256)}
  const raw=Array.from(bytes,(b)=>alphabet[b%alphabet.length]).join('');
  return 'VST-'+raw.slice(0,4)+'-'+raw.slice(4,8)+'-'+raw.slice(8,12);
}
function currentPromoCodeV249(){return postalPromoDraftV249||(postalPromoDraftV249=newPromoCodeV249())}
function postalImageSectorsV249(src){
  src=src&&typeof src==='object'?src:{};
  const raw=src.imageSectors&&typeof src.imageSectors==='object'?src.imageSectors:{};
  const clean=a=>(Array.isArray(a)?a:[]).map(x=>String(x||'').trim()).filter(Boolean).slice(0,6);
  const tourism=clean(raw.tourism); if(!tourism.length&&src.frontPark)tourism.push(String(src.frontPark));
  const property=clean(raw.property); if(!property.length)property.push(String(src.frontFacade||src.frontFaçade||'postal-facade-versatil.png'));
  const experience=clean(raw.experience); if(!experience.length){if(src.frontRoom)experience.push(String(src.frontRoom));if(src.frontPool)experience.push(String(src.frontPool));}
  if(!experience.length)experience.push(String(POSTAL_FIXED_PHOTOS_V173.pool||DEFAULT_POSTAL_CONFIG.frontPool||''));
  return {tourism:tourism.slice(0,6),property:property.slice(0,6),experience:experience.slice(0,6)};
}
function postalCombinationKeyV249(sectors){
  return JSON.stringify(['tourism','property','experience'].map(k=>(sectors[k]||[]).map(String)));
}
function nextPostalCompositionV249(){
  const cfg=postalConfigV180(),sectors=postalImageSectorsV249(cfg),names=['tourism','property','experience'];
  const pools=names.map(k=>(sectors[k]||[]).filter(Boolean));
  if(pools.some(a=>!a.length))return {images:[cfg.frontPark,cfg.frontFacade,cfg.frontPool].filter(Boolean),indexes:[0,0,0]};
  const signature=postalCombinationKeyV249(sectors);
  let state=null;try{state=JSON.parse(localStorage.getItem('versatil_postal_combo_cycle_v249')||'null')}catch(e){}
  if(!state||state.signature!==signature||!Array.isArray(state.order)||state.index>=state.order.length){
    const combos=[];
    for(let a=0;a<pools[0].length;a++)for(let b=0;b<pools[1].length;b++)for(let c=0;c<pools[2].length;c++)combos.push([a,b,c]);
    for(let i=combos.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[combos[i],combos[j]]=[combos[j],combos[i]]}
    state={signature,order:combos,index:0};
  }
  const indexes=state.order[state.index++]||[0,0,0];
  try{localStorage.setItem('versatil_postal_combo_cycle_v249',JSON.stringify(state))}catch(e){}
  return {indexes,images:indexes.map((idx,i)=>pools[i][idx])};
}
function currentPostalCompositionV249(){return postalCompositionDraftV249||(postalCompositionDraftV249=nextPostalCompositionV249())}
function resetPostalDraftV249(){postalCompositionDraftV249=null;postalPromoDraftV249=''}
function postalTourismItem(){
  try{
    const semester=(()=>{const d=new Date();return d.getFullYear()+'-'+(d.getMonth()<6?'H1':'H2')})();
    const key='versatil_postal_tour_'+semester;
    const tourismRoot=(db.leisureGuide||[]).find(n=>n.parentId===''&&String(n.name).toUpperCase().includes('TURISMO'));
    const all=[];
    const walk=id=>{
      for(const n of leisureChildren(id)){
        if(n.type==='place'&&n.imageUrl)all.push(n);
        else if(n.type==='group')walk(n.id);
      }
    };
    if(tourismRoot)walk(tourismRoot.id);
    if(!all.length)return {name:'Cuiabá',imageUrl:'leisure-assets/turismo.svg',mapQuery:'Cuiabá MT'};
    let idx=0;
    try{idx=Number(localStorage.getItem(key)||0)%all.length}catch(e){idx=0}
    const item=all[idx]||all[0];
    try{localStorage.setItem(key,String((idx+1)%all.length))}catch(e){
      console.warn('Rotação do postal sem persistência local:',e);
    }
    return item;
  }catch(e){
    console.warn('Falha ao selecionar imagem turística do postal:',e);
    return {name:'Cuiabá',imageUrl:'leisure-assets/turismo.svg',mapQuery:'Cuiabá MT'};
  }
}
function postalConfigV180(){
  const src=db.postalConfig&&typeof db.postalConfig==='object'?db.postalConfig:{};
  const sectors=postalImageSectorsV249(src);
  return {
    ...src,
    message:String(src.message||'').trim()||POSTAL_TEXT_V180.message,
    couponText:String(src.couponText||'').trim()||POSTAL_TEXT_V180.couponText,
    address:String(src.address||'').trim()||DEFAULT_POSTAL_CONFIG.address,
    phone:String(src.phone||'').trim()||DEFAULT_POSTAL_CONFIG.phone,
    site:String(src.site||'').trim()||'https://www.starlis.com.br',
    imageSectors:sectors,
    frontPark:sectors.tourism[0]||POSTAL_FIXED_PHOTOS_V173.park,
    frontFacade:sectors.property[0]||'postal-facade-versatil.png',
    frontRoom:sectors.experience[0]||DEFAULT_POSTAL_CONFIG.frontRoom,
    frontPool:sectors.experience[1]||sectors.experience[0]||POSTAL_FIXED_PHOTOS_V173.pool||DEFAULT_POSTAL_CONFIG.frontPool
  };
}

