function bindPostalValidation(){
  const name=document.getElementById('postalRecipientName'),email=document.getElementById('postalRecipientEmail'),sender=document.getElementById('postalSenderName');
  if(!name||!email||!sender)return;
  [name,email,sender].forEach(el=>el.addEventListener('input',updatePostalFlipV170));
  updatePostalFlipV170();
}
function updatePostalFlipV170(){
  const name=document.getElementById('postalRecipientName'),email=document.getElementById('postalRecipientEmail'),sender=document.getElementById('postalSenderName'),btn=document.getElementById('postalFlipBtn'),err=document.getElementById('postalError');
  if(!name||!email||!sender||!btn)return;
  const em=email.value.trim().toLowerCase(),valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em),self=em===String(session?.email||'').toLowerCase();
  if(err){
    err.textContent=self?'Você não pode enviar o postal para o mesmo e-mail do acesso.':'';
    err.classList.toggle('postal-self-email-warning-v212',self);
  }
  btn.style.display=(name.value.trim()&&valid&&sender.value.trim()&&!self&&!document.getElementById('postalCard')?.classList.contains('flipped'))?'block':'none';
}
function flipPostalV170(){
  updatePostalFlipV170();const btn=document.getElementById('postalFlipBtn');if(!btn||btn.style.display==='none')return;
  const card=document.getElementById('postalCard');card?.classList.add('flipped');btn.style.display='none';
  const status=document.getElementById('postalStatus');if(status)status.textContent='Postal virado. O botão “Enviar” aparecerá em 7 segundos.';
  setTimeout(()=>{const s=document.getElementById('postalSendBtn');if(s)s.style.display='block';if(status)status.textContent='Pronto para enviar.'},7000);
}
async function sendPostalV170(){
  const card=document.getElementById('postalCard');
  const btn=document.getElementById('postalSendBtn');
  const status=document.getElementById('postalStatus');
  if(!card||card.classList.contains('sending')||postalAlreadySentV171())return;

  const recipientName=document.getElementById('postalRecipientName')?.value.trim()||'';
  const recipientEmail=document.getElementById('postalRecipientEmail')?.value.trim()||'';
  const senderName=document.getElementById('postalSenderName')?.value.trim()||session?.name||'';
  const self=recipientEmail.toLowerCase()===String(session?.email||'').toLowerCase();
  const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail);

  if(!recipientName||!valid||!senderName||self){
    updatePostalFlipV170();
    if(status)status.textContent=self?'Use um e-mail diferente do e-mail de acesso.':'Revise nome, e-mail e assinatura.';
    return;
  }

  if(btn)btn.style.display='none';
  card.classList.add('sending');
  if(status)status.textContent='Preparando e enviando seu postal…';
  showVersatilLoading('Enviando postal…');

  try{
    const cfg=postalConfigV180();
    const composition=currentPostalCompositionV249();
    const expandedSelected=await expandImageRefsV234({selectedImages:(composition.images||[]).slice(0,3)});
    const payload={
      action:'sendPostcard',
      clientVersion:APP_VERSION,
      sender:{name:senderName,email:session?.email||'',roomName:session?.roomName||room()?.name||''},
      recipient:{name:recipientName,email:recipientEmail},
      coupon:currentPromoCodeV249(),
      config:{message:cfg.message,couponText:cfg.couponText,address:cfg.address,phone:cfg.phone,site:cfg.site,selectedImages:expandedSelected.selectedImages||[]}
    };
    await centralPost('sendPostcard',payload);
    sessionStorage.setItem(POSTAL_SENT_ACCESS_KEY,'1');
    resetPostalDraftV249();
    if(status)status.textContent='Postal enviado com sucesso.';
    setTimeout(()=>{page='postal';render()},1200);
  }catch(e){
    console.warn('Falha ao enviar postal:',e);
    card.classList.remove('sending');
    if(btn)btn.style.display='block';
    if(status)status.textContent='Não foi possível enviar. Tente novamente.';
    alert('Não foi possível enviar o postal. Verifique sua conexão e tente novamente.');
  }finally{
    hideVersatilLoading();
  }
}
function signoutMessageV170(name){
  if(sessionActivity.order&&sessionActivity.route)return `Obrigado por seu pedido e aproveite seu passeio, até breve ${name}!`;
  if(sessionActivity.route)return `Maravilha ${name}, esperamos que aproveite seu passeio e curta Cuiabá!`;
  if(sessionActivity.order)return `Obrigado por seu pedido, até breve ${name}!`;
  return `Até breve ${name}!`;
}
function completeSignoutV170(){
  try{
    const role=session?.role||'';
    if(role==='client'&&page!=='confirmation')cart=[];
    try{sessionStorage.removeItem(POSTAL_SENT_ACCESS_KEY)}catch(e){}
    session=null;selectedCat='';expandedClientProductId='';page='catalog';adminPage='dashboard';
    resetSessionActivity();
    document.getElementById('signoutReadModal')?.remove();
    hideVersatilLoading();
    render();
    window.scrollTo(0,0);
  }catch(e){
    console.error('Conclusão de saída:',e);
    session=null;location.reload();
  }
}
function showSignoutPopupV170(){
  const name=session?.name||session?.email||'';
  const msg=session?.role==='admin'?`Até breve ${name}!`:signoutMessageV170(name);
  document.getElementById('signoutReadModal')?.remove();
  const m=document.createElement('div');m.id='signoutReadModal';m.className='signout-read-modal';
  m.innerHTML=`<div class="signout-read-box"><div class="signout-thumb">👍</div><h3>${esc(msg)}</h3><button class="btn primary signout-valeu" onclick="document.getElementById('signoutReadModal')?.remove();completeSignoutV170()">Obrigado!</button></div>`;
  document.body.appendChild(m);
}




function normasCandidatesV249(){
  const normalize=v=>String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  return (db.versatilGuide||[]).filter(sec=>String(sec?.id||'').trim().toLowerCase()==='normas'||normalize(sec?.name)==='normas gerais');
}
function normasSectionV247(){
  const list=normasCandidatesV249();
  return list.find(sec=>String(sec?.id||'').trim().toLowerCase()==='normas')||list[0]||null;
}
function isExcessNormasSectionV249(sec){
  const canonical=normasSectionV247();
  if(!canonical||!sec)return false;
  const normalize=v=>String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const isNorm=String(sec?.id||'').trim().toLowerCase()==='normas'||normalize(sec?.name)==='normas gerais';
  return isNorm&&sec!==canonical;
}

