function openNormasFromHeaderV176(btn){
  try{sessionStorage.setItem('normas_header_animation_stopped','1')}catch(e){}
  if(btn)btn.classList.add('normas-animation-stopped');
  restoreNormasDefinitiveV253();
  const canonical=normasSectionV247();
  // O cabeçalho é sempre compacto: o texto editorial da categoria nunca vira rótulo do botão.
  if(btn)btn.textContent='Normas gerais';
  page='versatil';
  render();
  const openTarget=()=>{
    const expectedId=String(canonical?.id||'normas');
    const details=[...document.querySelectorAll('details[data-versatil-section-id]')];
    const normalize=v=>String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const detail=details.find(el=>String(el.dataset.versatilSectionId||'')===expectedId)
      ||details.find(el=>String(el.dataset.versatilSectionId||'').toLowerCase()==='normas')
      ||details.find(el=>normalize(el.querySelector('summary span:nth-child(2)')?.textContent)==='normas gerais');
    if(detail){
      detail.open=true;
      detail.scrollIntoView({behavior:'smooth',block:'start'});
      adjustScrollBelowHeaderV177(true);
      return true;
    }
    return false;
  };
  setTimeout(()=>{if(!openTarget())setTimeout(openTarget,180)},80);
}
