const LEISURE_LISTS_MIGRATION_V241='versatil_leisure_lists_v241';
function normNameV241(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function leisureAliasesV241(name){
  const n=normNameV241(name);
  return ({
    'happy hour':['happy hour','happy hour jantar'],
    'sports bars':['sports bars','sports bar','bares esportivos'],
    'casas noturnas':['noite','casas noturnas'],
    'cachorro quente e baguncinhas':['cachorro quente e baguncinhas','cachorro quente','baguncinhas'],
    'espetinhos':['espetinhos','espetinho'],'hamburguerias':['hamburguerias','hamburgueria'],
    'carne':['carne','carnes'],'feijoadas reconhecidas':['feijoadas reconhecidas','feijoadas','feijoada'],
    'massas':['massas','massa'],'orientais':['orientais','oriental'],'peixe':['peixe','peixes'],
    'pizzarias':['pizzarias','pizzaria'],'comida regional':['comida regional','regional'],'rodizios':['rodizios','rodizio']
  })[n]||[n];
}
function applyLeisureListsV241(){
  if(localStorage.getItem(LEISURE_LISTS_MIGRATION_V241)==='1')return;
  for(const spec of LEISURE_LISTS_V241){
    const aliases=leisureAliasesV241(spec.name);
    const group=(db.leisureGuide||[]).find(x=>x.type==='group'&&aliases.includes(normNameV241(x.name)));
    if(!group)continue;
    if(normNameV241(spec.name)==='casas noturnas')group.name='Casas Noturnas';
    const ids=leisureDescendantIds(group.id);ids.delete(group.id);
    db.leisureGuide=(db.leisureGuide||[]).filter(x=>!ids.has(x.id));
    const base=Number(group.sort||0)+1;
    db.leisureGuide.push(...spec.items.map((x,i)=>({
      id:'lz_v241_'+normNameV241(spec.name).replace(/\s+/g,'_')+'_'+(i+1),parentId:group.id,type:'place',
      name:x.name,description:`Endereço: ${x.address||''}`,distance:x.distance||'',phone:x.phone||'',address:x.address||'',
      imageUrl:'',mapQuery:`${x.name}, ${x.address||'Cuiabá MT'}`,sort:base+i
    })));
  }
  save();markAdminLocalDirtyV226();
  try{localStorage.setItem(LEISURE_LISTS_MIGRATION_V241,'1')}catch(e){}
}

function deleteLeisureNode(nodeId){
  const n=(db.leisureGuide||[]).find(x=>x.id===nodeId);if(!n)return;
  const ids=leisureDescendantIds(nodeId);
  if(!confirm(`Excluir "${n.name}"${ids.size>1?` e ${ids.size-1} item(ns) dentro dele`:''}?`))return;
  for(const x of (db.leisureGuide||[]).filter(x=>ids.has(x.id)))rememberDeletionV241('leisure',x);
  db.leisureGuide=(db.leisureGuide||[]).filter(x=>!ids.has(x.id));save();markAdminLocalDirtyV226();render();
}





function recoveryNoticeV238(){
  const v=Array.isArray(db.versatilGuide)?db.versatilGuide.length:0;
  const s=Array.isArray(db.starlisGuide)?db.starlisGuide.length:0;
  return `<div class="notice success recovery-notice-v238"><b>Conteúdo recuperado e preservado.</b> Conheça o Versátil: ${v} categorias. Conheça a Starlis: ${s} categorias. A sincronização não pode mais excluir conteúdo existente.</div>`;
}

