async function normalizePostalImageV239(value){
  const v=String(value||'').trim();
  if(!v)return '';
  if(isImageRefV234(v))return v;
  if(/^data:image\//i.test(v))return await storeImageDataV234(v);
  return await urlToStoredImageV227(v);
}
let postalAdminDraftV249=null;
let postalAdminUploadPendingV249=Promise.resolve();
function ensurePostalAdminDraftV249(pc){
  if(postalAdminDraftV249)return;
  const sectors=postalImageSectorsV249(pc);
  postalAdminDraftV249={tourism:[...sectors.tourism],property:[...sectors.property],experience:[...sectors.experience]};
  for(const k of ['tourism','property','experience'])while(postalAdminDraftV249[k].length<6)postalAdminDraftV249[k].push('');
}
function postalAdminSectorHtmlV249(key,label){
  const arr=postalAdminDraftV249?.[key]||Array(6).fill('');
  return `<section class="postal-admin-sector-v249"><h3>${esc(label)}</h3><div class="postal-admin-vault-v249">${Array.from({length:6},(_,i)=>{
    const src=arr[i]||'';
    return `<div class="postal-admin-slot-v249"><b>Imagem ${i+1}</b><div id="postal_${key}_${i}_preview" class="postal-admin-slot-preview-v249 ${src?'has-image':''}">${src?`<img src="${esc(src)}" alt=""><button type="button" class="btn red small" onclick="clearPostalAdminImageV249('${key}',${i})">Remover</button>`:'<span class="small muted">Sem imagem</span>'}</div><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onchange="handlePostalAdminImageV249(this,'${key}',${i})"></div>`;
  }).join('')}</div></section>`;
}
function renderPostalAdminSlotV249(key,index){
  const box=document.getElementById(`postal_${key}_${index}_preview`);if(!box)return;
  const src=String(postalAdminDraftV249?.[key]?.[index]||'');
  box.classList.toggle('has-image',!!src);
  box.innerHTML=src?`<img src="${esc(src)}" alt=""><button type="button" class="btn red small" onclick="clearPostalAdminImageV249('${key}',${index})">Remover</button>`:'<span class="small muted">Sem imagem</span>';
}
async function handlePostalAdminImageV249(input,key,index){
  const file=input?.files?.[0];if(!file)return;
  postalAdminUploadPendingV249=(async()=>{
    try{
      const optimized=await optimizeImageBlobV229(file);
      const stored=await storeImageDataV234(optimized);
      ensurePostalAdminDraftV249(postalConfigV180());
      postalAdminDraftV249[key][index]=stored;
      renderPostalAdminSlotV249(key,index);
    }catch(err){console.error(err);alert('Não foi possível processar esta imagem.');}
    finally{if(input)input.value='';}
  })();
  await postalAdminUploadPendingV249;
}
function clearPostalAdminImageV249(key,index){
  ensurePostalAdminDraftV249(postalConfigV180());
  postalAdminDraftV249[key][index]='';
  renderPostalAdminSlotV249(key,index);
}
async function savePostalAdminV249(){
  await postalAdminUploadPendingV249;
  ensurePostalAdminDraftV249(postalConfigV180());
  const sectors={};
  for(const k of ['tourism','property','experience'])sectors[k]=(postalAdminDraftV249[k]||[]).map(x=>String(x||'').trim()).filter(Boolean).slice(0,6);
  if(Object.values(sectors).some(a=>!a.length))return alert('Mantenha pelo menos uma imagem em cada um dos 3 setores do postal.');
  db.postalConfig={...(db.postalConfig||{}),
    address:document.getElementById('postal_admin_address')?.value.trim()||'',
    phone:document.getElementById('postal_admin_phone')?.value.trim()||'',
    message:document.getElementById('postal_admin_message')?.value.trim()||'',
    couponText:document.getElementById('postal_admin_coupon')?.value.trim()||'',
    imageSectors:sectors,
    frontPark:sectors.tourism[0]||'',
    frontFacade:sectors.property[0]||'',
    frontFaçade:sectors.property[0]||'',
    frontRoom:sectors.experience[0]||'',
    frontPool:sectors.experience[1]||sectors.experience[0]||''
  };
  postalAdminDraftV249=null;
  resetPostalDraftV249();
  try{localStorage.removeItem('versatil_postal_combo_cycle_v249')}catch(e){}
  save();markAdminLocalDirtyV226();alert('Acervo do postal salvo. Use Publicar alterações no cabeçalho.');render();
}
